solution.solution.cpp:
#include <algorithm>
#include <deque>
#include <optional>
#include <utility>

struct Snapshot { double time; double x; double y; };

class Interpolator
{
public:
    Interpolator(double delay, double maxExtrapolation) : delay_{ delay }, maxExtrapolation_{ maxExtrapolation } {}

    void add(const Snapshot& s)
    {
        if (!snapshots_.empty() && s.time <= snapshots_.back().time) return;
        snapshots_.push_back(s);
        if (snapshots_.size() > 32) snapshots_.pop_front();
    }

    std::optional<std::pair<double, double>> positionAt(double now) const
    {
        if (snapshots_.empty()) return std::nullopt;
        const double t{ now - delay_ };
        const Snapshot& first{ snapshots_.front() };
        const Snapshot& last{ snapshots_.back() };
        if (t <= first.time) return std::pair{ first.x, first.y };
        if (t > last.time)
        {
            if (snapshots_.size() == 1) return std::pair{ last.x, last.y };
            const Snapshot& before{ snapshots_[snapshots_.size() - 2] };
            const double span{ last.time - before.time };
            const double ahead{ std::min(t - last.time, maxExtrapolation_) };
            return std::pair{ last.x + (last.x - before.x) / span * ahead, last.y + (last.y - before.y) / span * ahead };
        }
        for (std::size_t i{ 1 }; i < snapshots_.size(); ++i)
        {
            const Snapshot& a{ snapshots_[i - 1] };
            const Snapshot& b{ snapshots_[i] };
            if (t > b.time) continue;
            const double f{ (t - a.time) / (b.time - a.time) };
            return std::pair{ a.x + (b.x - a.x) * f, a.y + (b.y - a.y) * f };
        }
        return std::pair{ last.x, last.y };
    }

    std::size_t buffered() const { return snapshots_.size(); }

private:
    double delay_;
    double maxExtrapolation_;
    std::deque<Snapshot> snapshots_;
};

unitTests:
void expectAt(const std::optional<std::pair<double, double>>& p, double x, double y) {
    CHECK(p.has_value());
    if (p) { CHECK_NEAR(p->first, x, 1e-9); CHECK_NEAR(p->second, y, 1e-9); }
}
TEST("blending between snapshots") {
    Interpolator in{ 100, 50 };
    CHECK(!in.positionAt(500).has_value());
    in.add({ 100, 0, 0 });
    in.add({ 150, 10, 0 });
    in.add({ 200, 20, 10 });
    expectAt(in.positionAt(275), 15, 5);
    expectAt(in.positionAt(250), 10, 0);
    expectAt(in.positionAt(300), 20, 10);
    expectAt(in.positionAt(150), 0, 0);
    expectAt(in.positionAt(-1000), 0, 0);
}
TEST("a lost snapshot is a wider gap") {
    Interpolator in{ 100, 50 };
    in.add({ 100, 0, 0 });
    in.add({ 200, 20, 10 });
    in.add({ 300, 40, 10 });
    expectAt(in.positionAt(350), 30, 10);
}
TEST("extrapolating, then holding") {
    Interpolator in{ 100, 50 };
    in.add({ 150, 10, 0 });
    in.add({ 200, 20, 10 });
    expectAt(in.positionAt(320), 24, 14);
    expectAt(in.positionAt(350), 30, 20);
    expectAt(in.positionAt(1000), 30, 20);
    Interpolator one{ 100, 50 };
    one.add({ 100, 7, 8 });
    expectAt(one.positionAt(900), 7, 8);
}
TEST("old snapshots and the buffer size") {
    Interpolator in{ 100, 50 };
    in.add({ 100, 0, 0 });
    in.add({ 200, 20, 10 });
    in.add({ 180, 999, 999 });
    in.add({ 200, 999, 999 });
    CHECK_EQ(in.buffered(), 2u);
    expectAt(in.positionAt(250), 10, 5);
    for (int i{ 3 }; i < 60; ++i) in.add({ i * 100.0, i * 10.0, 0 });
    CHECK_EQ(in.buffered(), 32u);
    expectAt(in.positionAt(0), 280, 0);
}

